// ==UserScript==
// @name         DSLib (protected loader)
// @namespace    demonicscans-lib
// @version      1.8
// @description  Shared utilities for DS automator scripts — protected build (self-decoding). Readable master kept private.
// @author       Niokhy
// ==/UserScript==
// Protected build: the real library is XOR'd (key below) + base64, decoded and
// executed at load; it defines the global DSLib exactly like the readable one.
// Light protection only (the key is in this file). Readable master is private.
(function () {
    'use strict';
    var K = 'veyra';
    var P = "";
    try {
        var bin = atob(P);
        var bytes = new Uint8Array(bin.length);
        for (var i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i) ^ K.charCodeAt(i % K.length);
        (0, eval)(new TextDecoder('utf-8').decode(bytes));
    } catch (e) {
        console.error('[DSLib] protected loader failed:', e);
    }
})();
